export const MANAGED_MARKER = "kumiko-managed";

export type MarkerCommentStyle = "#" | "//";

// kumiko-testing has written this header into every bunfig since before the
// marker existed; it already means "generated, do not edit".
const BUNFIG_GENERATED_HEADER = "# Generated by kumiko-testing (";

const LOCAL_MARKER_RE = /^(?:#|\/\/) kumiko-managed: local(?:[ \t]+(.*))?$/;

export type ManagedMarker =
  | { readonly kind: "managed" }
  | { readonly kind: "local"; readonly reason: string }
  | { readonly kind: "unmarked" }
  | { readonly kind: "invalid"; readonly message: string };

// Docker requires `# syntax=` on line 1 and the kernel requires the shebang
// there, so the marker moves one line down in those files.
function isPreambleLine(line: string | undefined): boolean {
  return line !== undefined && (line.startsWith("#!") || line.startsWith("# syntax="));
}

function markerLineIndex(lines: readonly string[]): number {
  return isPreambleLine(lines[0]) ? 1 : 0;
}

function isMarkerLine(line: string | undefined): boolean {
  return line === `# ${MANAGED_MARKER}` || line === `// ${MANAGED_MARKER}`;
}

export function readManagedMarker(content: string): ManagedMarker {
  const lines = content.split("\n");
  const index = markerLineIndex(lines);
  const line = lines[index];
  if (!isMarkerLine(line) && !line?.startsWith(BUNFIG_GENERATED_HEADER))
    return { kind: "unmarked" };
  const local = LOCAL_MARKER_RE.exec(lines[index + 1] ?? "");
  if (local === null) return { kind: "managed" };
  const reason = local[1]?.trim() ?? "";
  if (reason === "") {
    return {
      kind: "invalid",
      message: `line ${index + 2}: "kumiko-managed: local" needs a reason, e.g. "# kumiko-managed: local extra build step for pdf-parse"`,
    };
  }
  return { kind: "local", reason };
}

/** Removes the marker line and a following local line; the bunfig header is content, not a marker. */
export function stripManagedMarker(content: string): string {
  const lines = content.split("\n");
  const index = markerLineIndex(lines);
  if (!isMarkerLine(lines[index])) return content;
  const removeCount = LOCAL_MARKER_RE.test(lines[index + 1] ?? "") ? 2 : 1;
  lines.splice(index, removeCount);
  return lines.join("\n");
}

export function addManagedMarker(content: string, style: MarkerCommentStyle): string {
  const lines = content.split("\n");
  lines.splice(markerLineIndex(lines), 0, `${style} ${MANAGED_MARKER}`);
  return lines.join("\n");
}
